create table if not exists public.whatsapp_subscriptions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,provider text not null default 'green-api' check(provider='green-api'),plan_code text not null check(plan_code in('basic','premium')),days_purchased integer not null check(days_purchased between 1 and 31),daily_price numeric(12,2) not null default 0 check(daily_price>=0),amount numeric(12,2) not null default 0 check(amount>=0),currency text not null default 'XOF',starts_at timestamptz not null default now(),ends_at timestamptz not null,status text not null default 'active' check(status in('pending','active','expired','cancelled')),payment_id uuid references public.payments(id) on delete set null,order_id uuid references public.orders(id) on delete set null,instance_id uuid references public.whatsapp_green_instances(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists whatsapp_subscriptions_org_idx on public.whatsapp_subscriptions(organization_id); create index if not exists whatsapp_subscriptions_ends_idx on public.whatsapp_subscriptions(ends_at); alter table public.whatsapp_subscriptions enable row level security;
